func (v *validator) walk(at string, value any, sch map[string]any) {
	sch = v.resolve(sch)
	if len(sch) == 0 {
		return
	}

	if want, ok := sch["type"].(string); ok && !typeMatches(want, value) {
		v.fail(at, "should be %s, not %s", want, kindOf(value))
		return
	}

