checked, moved, stale := tree.Verify(view)
if root == "" {
	fmt.Fprintf(os.Stderr, "cw: no working tree was found, so the snippets were not checked. "+
		"The page will say the code is unverified.\n")
}
if stale > 0 && !f.force {
	fmt.Fprintf(os.Stderr, "cw: %d snippet(s) are no longer in the working tree. Run cw check to see which, "+
		"fix them, or publish with --force to say it out loud on the page.\n", stale)
	os.Exit(1)
}

func BuildGitHubLinks(src *SourceView) *GitHubLinks {
	if src == nil {
		return nil
	}
	if src.Provider != "" && src.Provider != "github" {
		return nil
	}
	repo := strings.Trim(strings.TrimSpace(src.Repo), "/")
	out := &GitHubLinks{Repo: repo, Commit: src.Commit}

	if repo != "" && strings.Count(repo, "/") == 1 && src.Commit != "" {
		out.BlobBase = "https://github.com/" + repo + "/blob/" + src.Commit + "/"
	}
	if files := prFilesURL(src.URL); files != "" {
		out.PRFiles = files
		out.Anchors = map[string]string{}
		for _, f := range src.ChangedFiles {
			f = strings.TrimSpace(f)
			if f == "" {
				continue
			}
			out.Anchors[f] = diffAnchor(f)
		}
	}
	if out.BlobBase == "" && out.PRFiles == "" {
		return nil
	}
	return out
}

